args.command:
sed -i 's/ and i>=n-2//' h.py; python h.py; xtb init.xyz --opt --uhf 1 > opt.log 2>&1; tail -3 opt.log; grep "TOTAL ENERGY" opt.log|tail -1
python -c "
import numpy as np
L=open('xtbopt.xyz').read().split('\n')[2:]
at=[(l.split()[0],np.array(l.split()[1:],float)) for l in L if l.strip()]
for i,(e,p) in enumerate(at):
  for j,(e2,q) in enumerate(at):
    d=np.linalg.norm(q-p)
    if j>i and 'H' in (e,e2) and d<1.6 and not (e=='C' or e2=='C' ) : print(i,j,e,e2,round(d,2))
    if j>i and e=='Ti' and d<2.6: print(i,j,e2,round(d,2))
"
